input.contents:
// ============================================================
// DSE 2023 Mathematics Paper 1B — Style Library
// ============================================================

#let ML = 23mm
#let MR = 23mm
#let MT = 20mm
#let MB = 20mm

// ------------------------------------------------------------
// ANSWER SPACE
// ------------------------------------------------------------
#let answer-space(n: 5) = {
  for _ in range(n) {
    line(length: 100%, stroke: (thickness: 0.5pt, paint: rgb("#999999")))
    v(5.5mm)
  }
}

// ------------------------------------------------------------
// QUESTION FORMATTER
// ------------------------------------------------------------
#let fmt-question(qnum, marks, body, lines: none) = {
  block(width: 100%, breakable: true)[
    #grid(
      columns: (1fr, auto),
      column-gutter: 8mm,
      row-gutter: 0mm,
      align: (left + top, right + top),

      // Left: question number and body
      [
        #text(size: 11pt, font: "Times New Roman", weight: "bold")[#qnum.]
        #h(0.5em)
        #text(size: 11pt, font: "Times New Roman")[#body]
      ],

      // Right: marks
      [
        #v(-1pt)
        #text(size: 11pt, font: "Times New Roman")[(#marks)]
      ]
    )

    #v(4mm)
    #answer-space(n: if lines != none { lines } else { if marks <= 3 { 4 } else if marks <= 5 { 6 } else { 8 } })
  ]
}

// ------------------------------------------------------------
// SECTION HEADER
// ------------------------------------------------------------
#let fmt-section-header(section-label) = {
  block(width: 100%)[
    #v(2mm)
    #text(size: 11pt, font: "Times New Roman", weight: "bold")[
      Section #section-label
    ]
    #v(2mm)
    #line(length: 100%, stroke: (thickness: 0.8pt, paint: black))
    #v(3mm)
  ]
}

// ------------------------------------------------------------
// COVER PAGE
// ------------------------------------------------------------
#let fmt-cover = {
  page(
    paper: "a4",
    margin: (top: 25mm, bottom: 25mm, left: ML, right: MR),
    header: none,
    footer: none,
  )[
    // Top info box
    #align(center)[
      #box(
        width: 100%,
        stroke: (thickness: 1.5pt, paint: black),
        inset: (x: 12mm, y: 8mm),
      )[
        #set align(center)
        #text(size: 12pt, font: "Times New Roman", weight: "bold")[
          HONG KONG EXAMINATIONS AND ASSESSMENT AUTHORITY
        ]
        #v(4mm)
        #text(size: 11pt, font: "Times New Roman", weight: "bold")[
          HONG KONG DIPLOMA OF SECONDARY EDUCATION EXAMINATION
        ]
        #v(8mm)
        #text(size: 14pt, font: "Times New Roman", weight: "bold")[
          MATHEMATICS
        ]
        #v(2mm)
        #text(size: 12pt, font: "Times New Roman", weight: "bold")[
          Compulsory Part
        ]
        #v(8mm)
        #text(size: 13pt, font: "Times New Roman", weight: "bold")[
          PAPER 1
        ]
        #v(8mm)
        #grid(
          columns: (1fr, 1fr),
          column-gutter: 15mm,
          align: (left, left),

          [#text(size: 11pt, font: "Times New Roman")[Question-Answer Book]],
          [#text(size: 11pt, font: "Times New Roman")[Section B (2)]]
        )
      ]
    ]

    #v(12mm)

    // Time and marks info
    #set text(size: 10.5pt, font: "Times New Roman")
    #set par(leading: 0.7em, justify: false)

    #block(width: 100%)[
      #grid(
        columns: (auto, 1fr, auto),
        column-gutter: 8mm,
        align: (left, left, left),

        [Time allowed:], [2 hours 15 minutes], [],
        [Total marks:], [65], [(Section A: 30 marks; Section B: 35 marks)]
      )
    ]

    #v(10mm)

    // Instructions box
    #box(
      width: 100%,
      stroke: (thickness: 1pt, paint: black),
      inset: (x: 8mm, y: 8mm),
    )[
      #set text(size: 10.5pt, font: "Times New Roman")
      #set par(leading: 0.65em, justify: false)

      #text(weight: "bold")[INSTRUCTIONS]

      #v(3mm)

      #text(weight: "bold")[(1)] #h(0.5em) Write your Candidate Number in the space provided on Page 2.

      #v(2.5mm)

      #text(weight: "bold")[(2)] #h(0.5em) This book contains Section B (2) only. Section A and Section B (1) are printed in separate books.

      #v(2.5mm)

      #text(weight: "bold")[(3)] #h(0.5em) #text(weight: "bold")[You are advised to use an HB pencil to mark all the answers on the Answer Sheet for Section A]. The use of an eraser is permissible. You must mark the answers clearly; otherwise you will lose marks if the answers cannot be captured.

      #v(2.5mm)

      #text(weight: "bold")[(4)] #h(0.5em) Write your answers in the spaces provided in this Question-Answer Book for Section B. #text(weight: "bold")[Do NOT write in the margins.]

      #v(2.5mm)

      #text(weight: "bold")[(5)] #h(0.5em) #text(weight: "bold")[You are advised to use a ball-point pen to write your answers for Section B.]

      #v(2.5mm)

      #text(weight: "bold")[(6)] #h(0.5em) #text(weight: "bold")[Unless otherwise specified, all working must be clearly shown.]

      #v(2.5mm)

      #text(weight: "bold")[(7)] #h(0.5em) Unless otherwise specified, numerical answers should be either exact or correct to 3 significant figures.

      #v(2.5mm)

      #text(weight: "bold")[(8)] #h(0.5em) Supplementary answer sheets will be supplied on request. Write your Candidate Number, mark the question number box and stick a barcode label on each sheet, and fasten them with string INSIDE this book.

      #v(2.5mm)

      #text(weight: "bold")[(9)] #h(0.5em) #text(weight: "bold")[NO calculators can be used in this paper.]
    ]

    #v(1fr)

    // Bottom notice
    #align(center)[
      #text(size: 9pt, font: "Times New Roman", style: "italic")[
        © 2023 Hong Kong Examinations and Assessment Authority\
        All Rights Reserved
      ]
    ]

    #v(4mm)

    #align(center)[
      #text(size: 8pt, font: "Times New Roman")[
        23-E-MATH-CP 1–11 (2023-DSE-MATH-CP 1)
      ]
    ]
  ]
}

// ------------------------------------------------------------
// CANDIDATE NUMBER PAGE
// ------------------------------------------------------------
#let fmt-candidate-page = {
  page(
    paper: "a4",
    margin: (top: MT, bottom: MB, left: ML, right: MR),
    header: none,
    footer: {
      place(bottom + right, dy: -5mm)[
        #text(size: 9pt, font: "Times New Roman", fill: gray)[
          #context counter(page).display()
        ]
      ]
    },
  )[
    #v(5mm)
    #align(center)[
      #text(size: 11pt, font: "Times New Roman", weight: "bold")[
        Candidate Number
      ]
    ]

    #v(8mm)

    #align(center)[
      #grid(
        columns: 8,
        column-gutter: 3mm,
        row-gutter: 3mm,
        ..range(8).map(_ => 
          box(
            width: 15mm,
            height: 20mm,
            stroke: (thickness: 1pt, paint: black),
            inset: 0mm
          )[#align(center + horizon)[]]
        )
      )
    ]

    #v(1fr)

    #align(center)[
      #text(size: 10pt, font: "Times New Roman", style: "italic")[
        Page left blank intentionally
      ]
    ]
  ]
}

// ------------------------------------------------------------
// END PAGE
// ------------------------------------------------------------
#let fmt-end-page = {
  page(
    paper: "a4",
    margin: (top: MT, bottom: MB, left: ML, right: MR),
    header: none,
    footer: {
      place(bottom + right, dy: -5mm)[
        #text(size: 9pt, font: "Times New Roman", fill: gray)[
          #context counter(page).display()
        ]
      ]
    },
  )[
    #v(1fr)
    #align(center + horizon)[
      #text(size: 14pt, font: "Times New Roman", weight: "bold")[
        END OF PAPER
      ]
    ]
    #v(1fr)
  ]
}

// ------------------------------------------------------------
// QUESTION PAGE
// ------------------------------------------------------------
#let fmt-question-page(sec, page-num) = {
  page(
    paper: "a4",
    margin: (top: MT, bottom: MB, left: ML, right: MR),
    header: none,
    footer: {
      place(bottom + right, dy: -5mm)[
        #text(size: 9pt, font: "Times New Roman", fill: gray)[
          #context counter(page).display()
        ]
      ]
    },
  )[
    #fmt-section-header(sec.section-label)

    #for q in sec.questions {
      fmt-question(q.qnum, q.marks, q.body, lines: q.at("lines", default: none))
      if q.at("pagebreak", default: false) { pagebreak(weak: true) }
    }
  ]
}

// ------------------------------------------------------------
// ASSEMBLE FULL PAPER
// ------------------------------------------------------------
#let make-paper = {
  import "content.typ": exam-content

  // Set document defaults
  set text(font: "Times New Roman", size: 11pt)
  set par(leading: 0.65em, justify: false)

  fmt-cover
  fmt-candidate-page

  // Render sections
  for sec in exam-content {
    fmt-question-page(sec, 3)
  }

  fmt-end-page
}

