// ============================================================
// DSE 2023 Mathematics Paper 1B — Style Library
// ============================================================

#let ML = 23mm
#let MR = 23mm
#let MT = 20mm
#let MB = 20mm

// ------------------------------------------------------------
// ANSWER SPACE
// ------------------------------------------------------------
#let answer-space(n: 5) = {
  for _ in range(n) {
    line(length: 100%, stroke: (thickness: 0.5pt, paint: rgb("#999999")))
    v(5.5mm)
  }
}

// ------------------------------------------------------------
// QUESTION FORMATTER
// ------------------------------------------------------------
#let fmt-question(qnum, marks, body, lines: none) = {
  block(width: 100%, breakable: true)[
    #grid(
      columns: (1fr, auto),
      column-gutter: 8mm,
      row-gutter: 0mm,
      align: (left + top, right + top),

      // Left: question number and body
      [
        #text(size: 11pt, font: "Times New Roman", weight: "bold")[#qnum.]
        #h(0.5em)
        #text(size: 11pt, font: "Times New Roman")[#body]
      ],

      // Right: marks
      [
        #v(-1pt)
        #text(size: 11pt, font: "Times New Roman")[(#marks)]
      ]
    )

    #v(4mm)
    #answer-space(n: if lines != none { lines } else { if marks <= 3 { 4 } else if marks <= 5 { 6 } else { 8 } })
  ]
}

// ------------------------------------------------------------
// SECTION HEADER
// ------------------------------------------------------------
#let fmt-section-header(section-label) = {
  block(width: 100%)[
    #v(2mm)
    #text(size: 11pt, font: "Times New Roman", weight: "bold")[
