      ]

      #v(2mm)

      #text(size: 7pt)[
        23-E-MATH-CP 1–11 (2023-DSE-MATH-CP 1)
      ]
    ]
  ]
}

// ------------------------------------------------------------
// CANDIDATE NUMBER PAGE
// ------------------------------------------------------------
#let fmt-candidate-page = {
  page(
    paper: "a4",
    margin: (top: MT, bottom: MB, left: ML, right: MR),
    header: none,
    footer: {
      place(bottom + right, dy: -5mm)[
        #text(size: 9pt, font: "Times New Roman", fill: gray)[
          #context counter(page).display()
        ]
      ]
    },
  )[
    #v(5mm)
    #align(center)[
      #text(size: 11pt, font: "Times New Roman", weight: "bold")[
        Candidate Number
      ]
    ]

    #v(8mm)

    #align(center)[
      #grid(
        columns: 8,
        column-gutter: 3mm,
        row-gutter: 3mm,
        ..range(8).map(_ => 
          box(
            width: 15mm,
            height: 20mm,
            stroke: (thickness: 1pt, paint: black),
            inset: 0mm
          )[#align(center + horizon)[]]
        )
      )
    ]

    #v(1fr)

    #align(center)[
      #text(size: 10pt, font: "Times New Roman", style: "italic")[
        Page left blank intentionally
      ]
    ]
  ]
}

// ------------------------------------------------------------
// END PAGE
// ------------------------------------------------------------
#let fmt-end-page = {
  page(
    paper: "a4",
    margin: (top: MT, bottom: MB, left: ML, right: MR),
    header: none,
    footer: {
      place(bottom + right, dy: -5mm)[
        #text(size: 9pt, font: "Times New Roman", fill: gray)[
          #context counter(page).display()
        ]
      ]
    },
  )[
    #v(1fr)
    #align(center + horizon)[
      #text(size: 14pt, font: "Times New Roman", weight: "bold")[
        END OF PAPER
      ]
    ]
    #v(1fr)
  ]
}

// ------------------------------------------------------------
// QUESTION PAGE
// ------------------------------------------------------------
#let fmt-question-page(sec, page-num) = {
  page(
    paper: "a4",
    margin: (top: MT, bottom: MB, left: ML, right: MR),
    header: none,
    footer: {
      place(bottom + right, dy: -5mm)[
        #text(size: 9pt, font: "Times New Roman", fill: gray)[
          #context counter(page).display()
        ]
      ]
    },
  )[
    #fmt-section-header(sec.section-label)

    #for q in sec.questions {
      fmt-question(q.qnum, q.marks, q.body, lines: q.at("lines", default: none))
      if q.at("pagebreak", default: false) { pagebreak(weak: true) }
    }
  ]
}

// ------------------------------------------------------------
// ASSEMBLE FULL PAPER
// ------------------------------------------------------------
#let make-paper = {
  import "content.typ": exam-content

  // Set document defaults
  set text(font: "Times New Roman", size: 11pt)
  set par(leading: 0.65em, justify: false)

  // Extract all questions from all sections for the cover page marks table
  let all-questions = ()
  for sec in exam-content {
    all-questions += sec.questions
  }

  fmt-cover(questions: all-questions)
  fmt-candidate-page

  // Render sections
  for sec in exam-content {
    fmt-question-page(sec, 3)
  }

  fmt-end-page
}

