\question{11}{4}
Let $f(x) = x^3 - 6x^2 + 9x - 2$.

\begin{enumerate}[label=(\alph*)]
  \item Find $f'(x)$.
  \item Find the coordinates of the local maximum and local minimum of the curve $y = f(x)$.
\end{enumerate}

\answerlines{12}

\question{12}{4}
The coordinates of the points $A$ and $B$ are $(2, -3)$ and $(7, 5)$ respectively.

\begin{enumerate}[label=(\alph*)]
  \item Find the equation of the perpendicular bisector of $AB$.
  \item A point $P$ lies on the perpendicular bisector of $AB$ such that $PA = PB = \sqrt{13}$. Find the coordinates of $P$.
\end{enumerate}

\answerlines{12}

\question{13}{4}
In Figure 1, $ABCD$ is a cyclic quadrilateral. $AC = 10$ cm, $BD = 8$ cm and $\angle ACB = 60°$.

\begin{enumerate}[label=(\alph*)]
  \item Find $\angle ADB$.
  \item Find the area of $\triangle ABD$.
\end{enumerate}

\answerlines{14}

\question{14}{4}
A bag contains 4 red balls and 6 white balls. Two balls are drawn at random from the bag, one after the other without replacement.

\begin{enumerate}[label=(\alph*)]
  \item Find the probability that both balls drawn are red.
  \item Given that the first ball drawn is red, find the probability that the second ball drawn is white.
\end{enumerate}

\answerlines{12}

\question{15}{4}
The following table shows the distribution of the marks (out of 100) obtained by 200 students in a test.

\begin{center}
\begin{tabular}{|c|c|c|c|c|}
\hline
Mark & 20--29 & 30--49 & 50--69 & 70--89 \\ \hline
Number of students & 30 & 60 & 70 & 40 \\ \hline
\end{tabular}
\end{center}

\begin{enumerate}[label=(\alph*)]
  \item Find the mean mark of the students.
  \item Find the standard deviation of the marks.
\end{enumerate}

\answerlines{14}

\question{16}{4}
The position vectors of the points $A$ and $B$ relative to an origin $O$ are $\vec{OA} = 2\mathbf{i} + 3\mathbf{j}$ and $\vec{OB} = 5\mathbf{i} - \mathbf{j}$ respectively.

\begin{enumerate}[label=(\alph*)]
  \item Find $\vec{AB}$.
  \item A point $P$ is on $AB$ such that $AP : PB = 2 : 1$. Find $\vec{OP}$.
\end{enumerate}

\answerlines{12}

\question{17}{3}
The roots of the equation $2x^2 - 3x + k = 0$, where $k$ is a constant, are $\alpha$ and $\beta$.

\begin{enumerate}[label=(\alph*)]
  \item Find, in terms of $k$, the value of $\alpha + \beta$ and $\alpha\beta$.
  \item If $\alpha^2 + \beta^2 = \dfrac{5}{4}$, find $k$.
\end{enumerate}

\answerlines{10}

\question{18}{4}
The equation of a circle is $x^2 + y^2 - 6x + 4y - 12 = 0$.

\begin{enumerate}[label=(\alph*)]
  \item Find the centre and the radius of the circle.
  \item A point $P(2, k)$, where $k$ is a constant, lies on the circle. Find the value(s) of $k$.
\end{enumerate}

\answerlines{12}

\question{19}{4}
A factory produces two types of pens, $A$ and $B$. Each pen of type $A$ takes 2 minutes to make and yields a profit of \$3. Each pen of type $B$ takes 3 minutes to make and yields a profit of \$4. There are 480 minutes available each day, and at most 180 pens can be made each day. Let $x$ and $y$ be the number of pens of type $A$ and type $B$ made each day respectively.

\begin{enumerate}[label=(\alph*)]
  \item Write down two inequalities, in terms of $x$ and $y$, to represent the constraints.
  \item Find the maximum daily profit.
\end{enumerate}

\answerlines{14}

